#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(Seurat);library(SeuratObject);library(ggplot2)})
if(requireNamespace("future",quietly=TRUE))future::plan("sequential");options(future.globals.maxSize=200*1024^3)
root<-normalizePath(file.path(getwd(),"subtype"),mustWork=TRUE);r4<-file.path(root,"round4_final");source(file.path(r4,"code","00_round4_config.R"));source(file.path(r4,"code","01_round4_marker_panels.R"))
lineage<-Sys.getenv("ROUND4_OBJECT",unset="");if(!lineage%in%names(round4_marker_panels))stop("Set ROUND4_OBJECT");out<-file.path(r4,"02_reclustering",lineage);tab<-file.path(out,"tables");fig<-file.path(out,"figures");con<-file(file.path(r4,"logs",paste0("Round4_",lineage,"_marker_audit.log")),"wt");sink(con,type="output",split=TRUE);sink(con,type="message")
object<-qs2::qs_read(file.path(out,paste0(lineage,"_round4_final_preannotation.qs2")));DefaultAssay(object)<-"RNA";layers<-Layers(object[["RNA"]],search=NA);if(length(grep("^data(\\.|$)",layers))>1L)object<-JoinLayers(object,assay="RNA")
cycle<-c("MKI67","TOP2A","UBE2C","BIRC5","CENPF","RRM2","PCLAF","CDC20","TYMS","CDK1","CCNB1","CCNB2","CCNA2","CDCA3","CDCA8","TK1","NUSAP1","ASPM","TPX2","AURKA","AURKB","KIF11","KIF20A","KIF2C","KIF4A","KIFC1","MCM2","MCM3","MCM4","MCM5","MCM6","MCM7","PCNA","HMGB2","STMN1","TUBA1B")
topn<-function(x,mode="raw"){z<-x;if(mode=="friendly")z<-z[!grepl("^(MT-|RPL|RPS|ENSG)",z$gene)&z$gene!="MALAT1",,drop=FALSE];if(mode=="noncycle")z<-z[!z$gene%in%cycle&!grepl("^HIST[1-4]",z$gene),,drop=FALSE];fc<-intersect(c("avg_log2FC","avg_logFC"),names(z))[1];z<-z[order(as.character(z$cluster),-z[[fc]],z$p_val_adj),,drop=FALSE];do.call(rbind,lapply(split(z,z$cluster),head,n=50))}
sm<-list();for(rr in round4_config$resolutions){f<-round4_res_field(rr);Idents(object)<-object[[f,drop=TRUE]];m<-FindAllMarkers(object,assay="RNA",slot="data",only.pos=TRUE,min.pct=.10,logfc.threshold=.25,test.use="wilcox",densify=FALSE,verbose=TRUE);raw<-topn(m);friendly<-topn(m,"friendly");noncycle<-topn(m,"noncycle");stem<-file.path(tab,paste0("Round4_markers_res",rr));write.csv(m,paste0(stem,"_full.csv"),row.names=FALSE);write.csv(raw,paste0(stem,"_top50_raw.csv"),row.names=FALSE);write.csv(friendly,paste0(stem,"_top50_annotation_friendly.csv"),row.names=FALSE);write.csv(noncycle,paste0(stem,"_top50_non_cellcycle.csv"),row.names=FALSE);sm[[as.character(rr)]]<-data.frame(lineage=lineage,resolution=rr,object_clusters=length(unique(object[[f,drop=TRUE]])),marker_clusters=length(unique(m$cluster)),full_rows=nrow(m),top50_raw_rows=nrow(raw),top50_friendly_rows=nrow(friendly),top50_noncycle_rows=nrow(noncycle));rm(m,raw,friendly,noncycle);gc()};write.csv(do.call(rbind,sm),file.path(tab,"Round4_marker_output_summary.csv"),row.names=FALSE)
panels<-round4_marker_panels[[lineage]];panel<-do.call(rbind,lapply(names(panels),function(p)data.frame(program=p,gene=panels[[p]],stringsAsFactors=FALSE)));panel$present<-panel$gene%in%rownames(object);write.csv(panel,file.path(tab,"Round4_canonical_marker_panel_audit.csv"),row.names=FALSE);write.csv(panel[!panel$present,,drop=FALSE],file.path(tab,"Round4_missing_canonical_markers.csv"),row.names=FALSE);features<-unique(panel$gene[panel$present])
for(rr in round4_config$resolutions){f<-round4_res_field(rr);Idents(object)<-object[[f,drop=TRUE]];p<-DotPlot(object,features=features,assay="RNA",group.by=f,scale=TRUE,dot.scale=6)+RotatedAxis()+labs(x="marker",y="cluster")+theme_classic(base_size=10)+theme(axis.text.x=element_text(size=7));stem<-file.path(fig,paste0("Round4_",lineage,"_canonical_DotPlot_res",rr));w<-max(14,.25*length(features));ggsave(paste0(stem,".pdf"),p,width=w,height=8,limitsize=FALSE);ggsave(paste0(stem,".png"),p,width=w,height=8,dpi=300,bg="white",limitsize=FALSE)}
message("END Round4 marker audit ",lineage,"; RNA DATA ONLY; NO ANNOTATION");sink(type="message");sink(type="output");close(con)
